static int valid_digest(const char *s) {
  if (strlen(s) != 64) return 0;
  for (int i = 0; i < 64; ++i)
    if (!((s[i] >= '0' && s[i] <= '9') || (s[i] >= 'a' && s[i] <= 'f')))
      return 0;
  return 1;
}

int op_halt(void) {
  FILE *fp = fopen("/app/wickbin/layout.qmap", "r");
  if (!fp) return 1;

  char line[1024];
  if (!fgets(line, sizeof(line), fp) || strcmp(line, "QMAP1\n") != 0) {
    fclose(fp);
    return 1;
  }

  int rows = 0;
  while (fgets(line, sizeof(line), fp)) {
    char path[256], stored[65], extra;
    unsigned long long dev, ino, vma, off, sz;
    if (sscanf(line, "%255s %llu %llu %64s %llu %llu %llu %c",
               path, &dev, &ino, stored, &vma, &off, &sz, &extra) != 7 ||
        !valid_digest(stored)) {
      fclose(fp);
      return 1;
    }
    char current[65];
    if (file_sha256_hex(path, current) != 0 || strcmp(stored, current) != 0) {
      fclose(fp);
      return 1;
    }
    ++rows;
  }
  int bad = ferror(fp) || rows == 0;
  fclose(fp);
  return bad ? 1 : 0;
}
